    : result;

  for await (const value of iterable) {
    if (signal.aborted) {
      break;
    }

    let data = value;
    let id: string | undefined = undefined;

    if (isTrackedEnvelope(data)) {
      id = data[0] as string;
      data = {
        id,
        data: data[1],
      };
    }

